import{_ as o,c as a,o as r,ag as n}from"./chunks/framework.Cycwnjj0.js";const i="/assets/affiliate-link-config-settings-of-azonpress.Dxe1gWzo.webp",s="/assets/global-affiliate-link-configuration-page.BOXEKHi6.webp",u="/assets/example-of-adding-quary-params.DXo30VdF.webp",d="/assets/open-desired-custom-product.BfZPhVAz.webp",l="/assets/settings-of-a-specific-custom-product.1uXgvb8a.webp",e="/assets/preview-of-added-query-params-in-url-of-custom-product.C8dkeVMQ.webp",k=JSON.parse('{"title":"Affiliate Link Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/miscellaneous/affiliate-link-configuration.md","filePath":"guide/miscellaneous/affiliate-link-configuration.md"}'),p={name:"guide/miscellaneous/affiliate-link-configuration.md"};function g(c,t,f,m,h,y){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="affiliate-link-configuration" tabindex="-1">Affiliate Link Configuration <a class="header-anchor" href="#affiliate-link-configuration" aria-label="Permalink to &quot;Affiliate Link Configuration&quot;">​</a></h1><p>In AzonPress, the &quot;<strong>Affiliate Link Configuration</strong>&quot; settings allow you to <strong>create</strong> an <strong>Affiliate link</strong> with <strong>Query Params</strong>. You can make query param affiliate links for any e-commerce website with only the Custom Product feature of AzonPress. This guide will help you through <strong>adding</strong> the <strong>Query Params</strong> to your product link with <strong>AzonPress</strong>.</p><h2 id="what-are-query-params" tabindex="-1">What are Query Params? <a class="header-anchor" href="#what-are-query-params" aria-label="Permalink to &quot;What are Query Params?&quot;">​</a></h2><p>Generally, query params are the parameters attached to the end of a URL and separated from the URL by a question mark (?). The section before the question mark is the path parameter, and the section after the question mark is the query. The path parameter defines the resource location, while the query parameter defines sort, pagination, or filter operations. The user&#39;s input (the query) is passed as a variable in the query parameter.</p><h2 id="add-query-params-with-global-affiliate-link-configuration" tabindex="-1">Add Query Params with Global Affiliate Link Configuration <a class="header-anchor" href="#add-query-params-with-global-affiliate-link-configuration" aria-label="Permalink to &quot;Add Query Params with Global Affiliate Link Configuration&quot;">​</a></h2><p>To learn how to add Query Params, follow the steps with screenshots below:</p><p>First, go to <strong>Settings</strong> from the <strong>AzonPress Navbar</strong> and click on <strong>Affiliate Link Configuration.</strong></p><p><img src="'+i+'" alt="Affiliate Link Config Settings of AzonPress"></p><p>Here, on the <strong>Global Affiliate Link Configuration</strong> page, you will find two domain options for configuring <strong>Query Params</strong> in your link. These are:</p><ul><li>Configure Params For amazon.com</li><li>Configure Params For eBay.com</li><li>You can add multiple domains as per your needs besides these two default ones.</li></ul><ol><li>First, give the domain name into <strong>the Affiliate domain name</strong> field from where you want to add your product and query param on that product link.</li><li>Now, to configure the query params in the existing domains, enter the query (as a text form) into the <strong>Link query params</strong> fields.</li><li>You can <strong>Delete</strong> the existing configuration domain anytime if needed just by clicking the <strong>Trash</strong> icon.</li><li>But, if you want to add more <strong>Link Query Params</strong> besides the default one under a domain, you can do this by clicking the <strong>Plus</strong> icon.</li><li>You can also <strong>Delete</strong> the <strong>Link Query Params</strong> by clicking the <strong>Trash</strong> icon except the default one.</li><li>Additionally, if you want to <strong>add more domains</strong> for query params, click the <strong>Add new domain</strong> button and follow the same process.</li></ol><p>Once you are done, click the <strong>Save</strong> button to save all the configurations or changes you made.</p><p><img src="'+s+'" alt="Global Affiliate Link Configuration page"></p><h3 id="example-of-adding-query-params" tabindex="-1">Example of Adding Query Params <a class="header-anchor" href="#example-of-adding-query-params" aria-label="Permalink to &quot;Example of Adding Query Params&quot;">​</a></h3><p>You can see the preview of the link of Amazon Products where the query param is added with a screenshot below –</p><p>Here, you can see that after the question mark, the query parameter &quot;<strong>tag=azonpress-10 &amp; utm_source=product10</strong>&quot; is added to the link under the amazon.com domain.</p><p><strong>Remember</strong>, the <strong>query params</strong> feature <strong>works only</strong> for the <strong>Custom Products</strong>.</p><p><img src="'+u+'" alt="Example of adding Query Params"></p><h2 id="add-query-param-directly-in-a-custom-product" tabindex="-1">Add Query Param Directly in a Custom Product <a class="header-anchor" href="#add-query-param-directly-in-a-custom-product" aria-label="Permalink to &quot;Add Query Param Directly in a Custom Product&quot;">​</a></h2><p>You will also find an <strong>Add Link Query Param</strong> option in your Single or Multiple <strong>Custom Products</strong> to <strong>add</strong> the <strong>Query Param</strong> for those <strong>specific custom products.</strong></p><p>The basic difference is that if you add query params from the Global Affiliate Link Configuration settings page, they will apply to all custom product links. But, if you add query params directly within a specific Custom Product, they will only apply to that product&#39;s URL.</p><p>To learn how to add query params directly inside a specific custom product, follow the steps with the screenshots below –</p><p>First, go to <strong>Custom Products</strong> from the <strong>AzonPress Navbar</strong> and open your desired <strong>Custom Product</strong> where you want to add the query param.</p><p><img src="'+d+'" alt="Open desired custom product"></p><p>Then, go to <strong>Settings</strong> from the right-hand sidebar and scroll down to the <strong>Add Link Query Params</strong> option.</p><p>Now, <strong>add</strong> your <strong>query param</strong> according to your needs and if you want to add more query params just click the <strong>Plus</strong> icon.</p><p>Finally, press the <strong>Save Template</strong> or <strong>Update &amp; Save Template</strong> button and the query param will be added to this specific product.</p><p><img src="'+l+'" alt="Settings of a specific custom product"></p><p>To see the preview of your added query param for this product, go to the <strong>product&#39;s preview</strong>, click &quot;<strong>buy now</strong>,&quot; and you&#39;ll see the query param at the end of the URL.</p><p><img src="'+e+'" alt="Preview of Added query param in custom product drift GIF"></p><p>Here, you can see that after the question mark, the query parameter &quot;<strong>tag=azonpress-50</strong>&quot; is added to the link of that specific custom product.</p><p><img src="'+e+'" alt="Preview of added query params in url of custom product"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',34)])])}const w=o(p,[["render",g]]);export{k as __pageData,w as default};
